KG_CODE("f:tests/test_workflow.py","\"\"\"Tests for the criteria engine and for session history.\n\nThe engine decides whether to take an irreversible action on someone's real\nrecord. Its gates are therefore tested the way a safety interlock is tested:\nby proving that the unsafe path is unreachable, not that the happy path works.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport json\nimport sys\nimport tempfile\nimport unittest\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\nsys.path.insert(0, str(ROOT / \"src\"))\n\nfrom autoskill import history, toolspec                        # noqa: E402\nfrom autoskill.protocol import ALL_METHODS, ProtocolError       # noqa: E402\nfrom autoskill.safety.permissions import VERB_RISK, Risk        # noqa: E402\nfrom autoskill.workflow import (Profile, classify,              # noqa: E402\n                                list_profiles, profiles_dir)\n\n\ndef _profile(**over):\n    base = {\n        \"name\": \"t\",\n        \"list\": {\"item\": r'(@e\\d+) link \"Item ([^\"]+)\"',\n                 \"identity_param\": \"id\"},\n        \"subject\": r\"Request from ([A-Za-z ]+) opened\",\n        \"gates\": [\n            {\"name\": \"complete\", \"label\": \"INCOMPLETE\",\n             \"all_of\": [r\"Request from [A-Za-z ]+ opened\", r'cell \"']},\n            {\"name\": \"exclude\", \"label\": \"Excluded\", \"on_match\": \"skip\",\n             \"any_of\": [r'cell \"(Legal hold[^\"]{0,20})\"']},\n            {\"name\": \"identify\", \"label\": \"UNRECOGNISED\",\n             \"capture\": r'cell \"(Refund [^\"]{3,30})\"'},\n        ],\n        \"steps\": [{\"do\": \"click\", \"match\": r'(@e\\d+) button \"Go\"',\n                   \"commit\": True, \"proves\": r'(@e\\d+) button \"Go\"'}],\n    }\n    base.update(over)\n    return Profile.from_dict(base)\n\n\ndef _body(*cells: str) -> str:\n    rows = \"\\n\".join(f'  @e9 cell \"{c}\"' for c in cells)\n    return \"Request from Sam Jones opened\\n\" + rows + '\\n  @e5 button \"Go\"'\n\n\nclass TestProfileValidation(unittest.TestCase):\n    \"\"\"A bad profile must fail at load time, not on the first live record.\"\"\"\n\n    def test_a_good_profile_loads(self):\n        self.assertEqual(_profile().name, \"t\")\n\n    def test_an_item_pattern_is_required(self):\n        with self.assertRaises(ProtocolError) as ctx:\n            _profile(list={\"item\": \"\"})\n        self.assertIn(\"list.item\", ctx.exception.error.message)\n\n    def test_a_broken_regex_is_caught_before_it_runs(self):\n        with self.assertRaises(ProtocolError) as ctx:\n            _profile(list={\"item\": r\"(@e\\d+) [unclosed\"})\n        self.assertIn(\"bad regex\", ctx.exception.error.message)\n\n    def test_the_irreversible_step_must_be_named(self):\n        with self.assertRaises(ProtocolError) as ctx:\n            _profile(steps=[{\"do\": \"click\", \"match\": r\"(@e\\d+) button\"}])\n        self.assertIn(\"commit\", ctx.exception.error.message)\n\n    def test_only_one_step_may_be_the_irreversible_one(self):\n        with self.assertRaises(ProtocolError) as ctx:\n            _profile(steps=[\n                {\"do\": \"click\", \"match\": r\"(@e\\d+) a\", \"commit\": True},\n                {\"do\": \"click\", \"match\": r\"(@e\\d+) b\", \"commit\": True}])\n        self.assertIn(\"more than one\", ctx.exception.error.message)\n\n    def test_an_unknown_step_verb_is_refused(self):\n        with self.assertRaises(ValueError):\n            _profile(steps=[{\"do\": \"teleport\", \"commit\": True}])\n\n    def test_an_unknown_surface_is_refused(self):\n        with self.assertRaises(ValueError):\n            _profile(surface=\"carrier-pigeon\")\n\n\nclass TestGatesFailClosed(unittest.TestCase):\n    \"\"\"`act` must be unreachable unless every gate passes.\"\"\"\n\n    def test_a_recognised_item_is_actionable(self):\n        v = classify(_profile(), _body(\"Refund requested 40 AED\"))\n        self.assertEqual(v.outcome, \"act\")\n        self.assertIn(\"Refund\", v.label)\n        self.assertEqual(v.subject, \"Sam Jones\")\n\n    def test_an_excluded_item_is_skipped_and_says_why(self):\n        v = classify(_profile(), _body(\"Legal hold active\"))\n        self.assertEqual(v.outcome, \"skip\")\n        self.assertIn(\"Excluded\", v.label)\n        self.assertIn(\"Legal hold\", v.label)\n\n    def test_a_half_rendered_page_is_incomplete_not_actionable(self):\n        \"\"\"The failure the old rule had: no exclusion marker on an\n        unfinished page read as 'nothing to exclude', so it acted.\"\"\"\n        half = 'Request from Sam Jones opened\\n  @e5 button \"Go\"'\n        v = classify(_profile(), half)\n        self.assertEqual(v.outcome, \"incomplete\")\n        self.assertNotEqual(v.outcome, \"act\")\n\n    def test_an_unrecognised_case_is_skipped_not_acted_on(self):\n        v = classify(_profile(), _body(\"Something nobody modelled\"))\n        self.assertEqual(v.outcome, \"skip\")\n        self.assertIn(\"UNRECOGNISED\", v.label)\n\n    def test_completeness_is_judged_before_exclusion(self):\n        \"\"\"Order matters: judging exclusion on a half-drawn page is the bug.\"\"\"\n        v = classify(_profile(), \"Request from Sam Jones opened\")\n        self.assertEqual(v.gate, \"complete\")\n\n    def test_exclusion_beats_identification(self):\n        v = classify(_profile(), _body(\"Refund requested 40 AED\",\n                                       \"Legal hold active\"))\n        self.assertEqual(v.outcome, \"skip\")\n        self.assertEqual(v.gate, \"exclude\")\n\n\nclass TestEngineIsSiteAgnostic(unittest.TestCase):\n    \"\"\"The engine must name no system; the profile carries all of that.\"\"\"\n\n    def test_no_site_specific_strings_in_the_engine(self):\n        \"\"\"The CODE must name no system.\n\n        The module docstring is exempt and is stripped first: it explains why\n        the refactor happened, and that history is worth keeping. What must\n        not survive is a site's vocabulary in the logic.\n        \"\"\"\n        src = (ROOT / \"src\" / \"autoskill\" / \"workflow.py\").read_text(encoding=\"utf-8\")\n        code = src.split('\"\"\"', 2)[-1]\n        for word in (\"Oracle\", \"Fusion\", \"bpmWorklist\", \"FuseWelcome\",\n                     \"Changed Personal Information\", '\"Claim\"'):\n            self.assertNotIn(word, code,\n                             f\"{word!r} leaked into the engine's logic\")\n\n    def test_the_shipped_profiles_all_load(self):\n        rows = list_profiles()\n        self.assertTrue(rows)\n        for r in rows:\n            self.assertNotIn(\"error\", r, r.get(\"name\"))\n\n    def test_oracle_is_now_data_not_code(self):\n        p = profiles_dir() / \"oracle-cpi.json\"\n        self.assertTrue(p.exists())\n        doc = json.loads(p.read_text(encoding=\"utf-8\"))\n        self.assertIn(\"bpmWorklistTaskId\", json.dumps(doc))\n        prof = Profile.load(p)\n        self.assertEqual([g.name for g in prof.gates],\n                         [\"complete\", \"exclude-family\", \"identify\"])\n        self.assertEqual(sum(1 for s in prof.steps if s.commit), 1)\n\n    def test_a_template_exists_for_any_other_queue(self):\n        p = profiles_dir() / \"TEMPLATE.json\"\n        self.assertTrue(p.exists())\n        Profile.load(p)           # must be a working example, not prose\n\n\nclass TestReachSequence(unittest.TestCase):\n    \"\"\"An empty queue and a page that navigated away look identical.\n\n    `walk.sh` knew how to get back to the list; the first version of this\n    engine did not, and slept through a full worklist because the tab was on\n    a detail page. The knowledge is now declared, not hardcoded.\n    \"\"\"\n\n    def test_reach_is_parsed_and_validated(self):\n        prof = _profile(list={\"item\": r'(@e\\d+) link \"Item\"',\n                              \"reach\": [{\"do\": \"click\",\n                                         \"match\": r'(@e\\d+) link \"Inbox\"'},\n                                        {\"do\": \"sleep\", \"seconds\": 2}]})\n        self.assertEqual([s.kind for s in prof.reach], [\"click\", \"sleep\"])\n\n    def test_a_broken_reach_pattern_is_caught_at_load(self):\n        with self.assertRaises(ProtocolError) as ctx:\n            _profile(list={\"item\": r'(@e\\d+) link \"Item\"',\n                           \"reach\": [{\"do\": \"click\", \"match\": \"(unclosed\"}]})\n        self.assertIn(\"bad regex\", ctx.exception.error.message)\n\n    def test_reach_may_not_contain_an_irreversible_step(self):\n        \"\"\"Navigation is not an action; a commit here would be a trap.\"\"\"\n        prof = _profile(list={\"item\": r'(@e\\d+) link \"Item\"',\n                              \"reach\": [{\"do\": \"click\",\n                                         \"match\": r'(@e\\d+) a'}]})\n        self.assertFalse(any(s.commit for s in prof.reach))\n\n    def test_a_profile_without_reach_still_works(self):\n        self.assertEqual(_profile().reach, [])\n\n    def test_the_engine_tries_reach_before_declaring_the_queue_empty(self):\n        src = (ROOT / \"src\" / \"autoskill\" / \"workflow.py\").read_text(encoding=\"utf-8\")\n        run = src.split(\"def run(self\")[1]\n        self.assertLess(run.index(\"self.reach_list(\"),\n                        run.index('\"queue is empty; waiting\"'))\n\n    def test_oracle_carries_the_sequence_walk_sh_used(self):\n        from autoskill.workflow import Profile\n        prof = Profile.load(profiles_dir() / \"oracle-cpi.json\")\n        self.assertTrue(prof.reach)\n        pats = \" \".join(s.pattern for s in prof.reach)\n        self.assertIn(\"Notifications\", pats)\n        # Deliberately no assertion about WHICH control. This line has\n        # broken twice in one session — \"Show All\", then \"Worklist\" — both\n        # times because measurement improved and the profile followed it,\n        # and both times the test would have blocked the correction. What\n        # has to hold is that the sequence exists and waits for what it\n        # clicks; which control that is belongs to the page, not to a test.\n        kinds = [st.kind for st in prof.reach]\n        self.assertIn(\"click\", kinds)\n        self.assertIn(\"wait\", kinds, \"the reach races the page\")\n        self.assertLess(kinds.index(\"wait\"), kinds.index(\"click\"),\n                        \"it clicks before waiting for the control\")\n\n    def test_the_template_shows_how_to_declare_one(self):\n        from autoskill.workflow import Profile\n        self.assertTrue(Profile.load(profiles_dir() / \"TEMPLATE.json\").reach)\n\n\nclass TestNothingWasQuietlyDropped(unittest.TestCase):\n    \"\"\"The scratch directory held real tools. Excluding it lost three.\n\n    `.tmp/` was 546 MB of browser profiles, so the copy skipped it whole —\n    and took `walk.sh`, `process.sh` and the transport probes with it. The\n    ledger calls them \"engine artifacts (reusable)\". They are kept now, and\n    this test is what stops the next bulk exclusion from doing it again.\n    \"\"\"\n\n    def test_the_superseded_walkers_are_preserved(self):\n        legacy = ROOT / \"skill\" / \"scripts\" / \"walker\" / \"legacy\"\n        for name in (\"walk.sh\", \"process.sh\", \"runbatch.sh\", \"cycle.sh\",\n                     \"watchdog-original.sh\", \"README.md\"):\n            self.assertTrue((legacy / name).exists(), name)\n\n    def test_the_transport_probes_are_preserved(self):\n        diag = ROOT / \"skill\" / \"scripts\" / \"diagnostics\"\n        for name in (\"cdp_probe.py\", \"daemon_spy.py\", \"daemon_spy2.py\",\n                     \"delta_test.py\", \"thread_test.py\", \"README.md\"):\n            self.assertTrue((diag / name).exists(), name)\n\n    def test_the_field_notes_survived_and_carry_no_real_names(self):\n        \"\"\"Checked by SHAPE, not by a list.\n\n        Listing the real surnames here would put them back into the repository\n        to prove they are not in it. Matching the shape instead also catches\n        names nobody thought to list — which is the failure mode a fixed list\n        has.\n        \"\"\"\n        import re\n        notes = ROOT / \"A-Project-Knowledge\" / \"field-notes-2026-09.md\"\n        self.assertTrue(notes.exists())\n        text = notes.read_text(encoding=\"utf-8\")\n        # Arabic/Emirati surname shapes that survived the original scrub:\n        # \"Al Something\", \"AlSomething\", \"Al-Something\".\n        leaked = re.findall(r\"\bAl[\\s-]?[A-Z][a-z]{2,}\", text)\n        self.assertEqual(leaked, [], f\"real surnames left in the notes: {leaked}\")\n        # Personal references must be pseudonyms, and there must be some.\n        self.assertRegex(text, r\"Person-\\d\")\n        self.assertIn(\"Names redacted\", text)\n\n    def test_the_legacy_readme_says_what_replaced_each_one(self):\n        readme = (ROOT / \"skill\" / \"scripts\" / \"walker\" / \"legacy\"\n                  / \"README.md\").read_text(encoding=\"utf-8\")\n        for token in (\"walk.sh\", \"process.sh\", \"workflow\", \"fail-open\"):\n            self.assertIn(token, readme, token)\n\n\nclass TestFlowIsGoverned(unittest.TestCase):\n    def test_every_flow_verb_is_classified(self):\n        for m in (m for m in ALL_METHODS if m.startswith(\"flow.\")):\n            self.assertIn(m, VERB_RISK, m)\n\n    def test_starting_an_unattended_run_needs_approval_in_guarded(self):\n        \"\"\"It acts on real records; guarded mode must ask.\"\"\"\n        self.assertIs(VERB_RISK[\"flow.start\"], Risk.DESTRUCTIVE)\n\n    def test_reading_a_run_is_free(self):\n        for m in (\"flow.list\", \"flow.status\", \"flow.validate\"):\n            self.assertIs(VERB_RISK[m], Risk.READ, m)\n\n    def test_the_tools_are_exposed(self):\n        names = {t[\"name\"] for t in toolspec.TOOLS}\n        for n in (\"flow_list\", \"flow_validate\", \"flow_status\", \"flow_start\",\n                  \"flow_reconcile\"):\n            self.assertIn(n, names)\n\n\nclass TestDurableRecord(unittest.TestCase):\n    \"\"\"Moved here when the logic moved. Coverage follows the code.\n\n    These five behaviours were proven against the Oracle script; they are the\n    reason the engine can be trusted with an irreversible action, so they are\n    re-proven against the engine rather than retired with the script.\n    \"\"\"\n\n    def runner(self, **kw):\n        from autoskill.workflow import FlowRunner\n        home = Path(tempfile.mkdtemp())\n        r = FlowRunner(_profile(), home=home, on_event=lambda *_: None, **kw)\n        return r\n\n    def test_identity_round_trips_whole_never_a_prefix(self):\n        \"\"\"A stored prefix compared against a full id never matches, and the\n        dedup then silently never fires.\"\"\"\n        r = self.runner()\n        full = \"415c60cb-5f5a-4389-b914-8721c89ae76a\"\n        r.journal_append(action=\"acted\", identity=full, subject=\"S\",\n                         summary=\"New Refund [415c60cb]\")\n        self.assertIn(full, r.decided())\n\n    def test_a_failed_attempt_is_not_treated_as_decided(self):\n        r = self.runner()\n        r.journal_append(action=\"failed\", identity=\"aaaa-bbbb\", subject=\"S\",\n                         summary=\"x\")\n        self.assertNotIn(\"aaaa-bbbb\", r.decided())\n\n    def test_a_dispatched_but_unconfirmed_item_still_counts_as_decided(self):\n        \"\"\"`committing` with no `acted` is the honest unknown: it must not be\n        retried by a later run.\"\"\"\n        r = self.runner()\n        r.journal_append(action=\"committing\", identity=\"cccc\", subject=\"S\",\n                         summary=\"x\")\n        self.assertIn(\"cccc\", r.decided())\n\n    def test_intent_is_written_before_the_irreversible_call(self):\n        src = (ROOT / \"src\" / \"autoskill\" / \"workflow.py\").read_text(encoding=\"utf-8\")\n        body = src.split(\"def _execute\")[1]\n        self.assertLess(body.index('action=\"committing\"'),\n                        body.index('self.call(\"click\"'))\n        self.assertLess(body.index('self.call(\"click\"'),\n                        body.index('action=\"acted\"'))\n\n    def test_the_journal_is_flushed_to_disk_not_buffered(self):\n        src = (ROOT / \"src\" / \"autoskill\" / \"workflow.py\").read_text(encoding=\"utf-8\")\n        self.assertIn(\"os.fsync\", src)\n\n    def test_the_engine_never_reaches_the_bridge_directly(self):\n        \"\"\"Every step must pass the daemon, or it is neither gated nor logged.\"\"\"\n        src = (ROOT / \"src\" / \"autoskill\" / \"workflow.py\").read_text(encoding=\"utf-8\")\n        code = src.split('\"\"\"', 2)[-1]\n        self.assertNotIn(\"nmhost\", code)\n        self.assertNotIn(\"subprocess\", code)\n        self.assertIn(\"from .client import call\", code)\n\n\nclass TestReconcileCountsRowsNotCalls(unittest.TestCase):\n    \"\"\"`ok` from the ledger means the CALL succeeded, not that a row landed.\n\n    Dedup refuses a replay and still answers ok, so counting calls made a\n    reconcile that wrote nothing report \"5 written\". Found by running it\n    twice against a real workbook and checking the row count did not move.\n    \"\"\"\n\n    def runner(self):\n        from autoskill.workflow import FlowRunner\n        return FlowRunner(_profile(), home=Path(tempfile.mkdtemp()),\n                          on_event=lambda *_: None)\n\n    def test_a_refused_duplicate_is_not_counted_as_written(self):\n        r = self.runner()\n        r.ledger = Path(\"anything.xlsx\")\n        import autoskill.client as cli\n        real = cli.call\n        cli.call = lambda *a, **k: {\"ok\": True, \"result\": {\"rows_added\": 0}}\n        try:\n            self.assertFalse(r.ledger_row(\"s\", \"who\", \"Skipped\"))\n        finally:\n            cli.call = real\n\n    def test_a_real_append_is_counted(self):\n        r = self.runner()\n        r.ledger = Path(\"anything.xlsx\")\n        import autoskill.client as cli\n        real = cli.call\n        cli.call = lambda *a, **k: {\"ok\": True, \"result\": {\"rows_added\": 1}}\n        try:\n            self.assertTrue(r.ledger_row(\"s\", \"who\", \"Skipped\"))\n        finally:\n            cli.call = real\n\n    def test_reconcile_separates_written_from_already_present(self):\n        r = self.runner()\n        r.ledger = Path(\"anything.xlsx\")\n        r.journal_append(action=\"skipped\", identity=\"a\", subject=\"x\", summary=\"1\")\n        r.journal_append(action=\"acted\", identity=\"b\", subject=\"y\", summary=\"2\")\n        import autoskill.client as cli\n        real = cli.call\n        cli.call = lambda *a, **k: {\"ok\": True, \"result\": {\"rows_added\": 0}}\n        try:\n            out = r.reconcile()\n        finally:\n            cli.call = real\n        self.assertEqual(out[\"journal_rows\"], 2)\n        self.assertEqual(out[\"written\"], 0)\n        self.assertEqual(out[\"already_present\"], 2)\n        self.assertEqual(out[\"effect_state\"], \"none\")\n\n\nclass TestSessionTeardown(unittest.TestCase):\n    \"\"\"Ending a task must end everything the task created.\n\n    Two things survived `session stop` and should not have. Measured, not\n    assumed: after stopping every session, `rb.click @e1` was still accepted\n    and clicked a link in the user's own browser.\n    \"\"\"\n\n    def test_rb_reset_drops_every_ref(self):\n        from autoskill.rb import RbSurface\n        rb = RbSurface()\n        rb._refs = {1: {\"@e1\": {\"backend\": 9}}, 2: {\"@e1\": {}, \"@e2\": {}}}\n        rb._last_tab = 1\n        out = rb.reset()\n        self.assertEqual(out[\"refs_dropped\"], 3)\n        self.assertEqual(rb._refs, {})\n        self.assertIsNone(rb._last_tab)\n\n    def test_reset_touches_nothing_in_the_browser(self):\n        \"\"\"It forgets; it does not close, navigate or click.\"\"\"\n        from autoskill.rb import RbSurface\n        import autoskill.rb as rbmod\n        called = []\n        real = rbmod._call\n        rbmod._call = lambda *a, **k: called.append(a) or {}\n        try:\n            RbSurface().reset()\n        finally:\n            rbmod._call = real\n        self.assertEqual(called, [])\n\n    def test_a_dropped_ref_is_refused_afterwards(self):\n        from autoskill.rb import RbSurface\n        rb = RbSurface()\n        rb._refs = {7: {\"@e1\": {\"backend\": 9}}}\n        rb.reset()\n        with self.assertRaises(ProtocolError) as ctx:\n            rb._resolve(7, \"@e1\")\n        self.assertEqual(ctx.exception.error.code.value, \"unknown_ref\")\n\n    def test_stopping_a_session_resets_the_real_browser_surface(self):\n        src = (ROOT / \"src\" / \"autoskill\" / \"daemon.py\").read_text(encoding=\"utf-8\")\n        body = src.split(\"def _stop_session_locked\")[1].split(\"\\n    def \")[0]\n        self.assertIn(\"self.rb.reset()\", body)\n\n    def test_stopping_a_session_removes_its_scratch(self):\n        src = (ROOT / \"src\" / \"autoskill\" / \"daemon.py\").read_text(encoding=\"utf-8\")\n        body = src.split(\"def _stop_session_locked\")[1].split(\"\\n    def \")[0]\n        self.assertIn('\"scratch\"', body)\n        self.assertIn(\"rmtree\", body)\n\n    def test_an_unnamed_screenshot_is_not_left_in_the_shared_temp(self):\n        \"\"\"A screenshot is a picture of the user's screen. The system temp\n        directory keeps it forever and nobody empties it.\"\"\"\n        src = (ROOT / \"src\" / \"autoskill\" / \"handlers.py\").read_text(encoding=\"utf-8\")\n        body = src.split(\"def _screenshot\")[1].split(\"\\ndef \")[0]\n        self.assertIn('\"scratch\"', body)\n        self.assertNotIn(\"gettempdir\", body)\n\n    def test_reset_is_reachable_by_the_user_too(self):\n        names = {t[\"name\"] for t in toolspec.TOOLS}\n        self.assertIn(\"rb_reset\", names)\n        self.assertIs(VERB_RISK[\"rb.reset\"], Risk.BENIGN)\n\n\nclass TestSessionHistory(unittest.TestCase):\n    \"\"\"A finished session keeps its shape and nothing else.\"\"\"\n\n    def entries(self):\n        return [\n            {\"ts\": \"2026-01-01T10:00:00\", \"method\": \"session.start\",\n             \"outcome\": \"ok\", \"params\": {}},\n            {\"ts\": \"2026-01-01T10:00:01\", \"method\": \"desktop.open_app\",\n             \"outcome\": \"ok\", \"params\": {\"command\": \"WINWORD.EXE\"}},\n            {\"ts\": \"2026-01-01T10:00:02\", \"method\": \"desktop.type\",\n             \"outcome\": \"ok\", \"params\": {\"text\": \"hello\", \"ref\": \"@e3\"},\n             \"result\": {}},\n            {\"ts\": \"2026-01-01T10:00:03\", \"method\": \"desktop.report\",\n             \"outcome\": \"ok\", \"params\": {\"file\": \"C:/out/report.docx\"},\n             \"result\": {\"file\": \"C:/out/report.docx\"}},\n            {\"ts\": \"2026-01-01T10:00:04\", \"method\": \"browser.navigate\",\n             \"outcome\": \"error\", \"error\": \"refused\",\n             \"params\": {\"url\": \"https://example.com/a?token=secret&x=1\"}},\n        ]\n\n    def test_the_recipe_is_ordered_and_readable(self):\n        doc = history.summarise(self.entries(), \"abcd\")\n        self.assertEqual(doc[\"operations\"], 5)\n        self.assertEqual(doc[\"failed\"], 1)\n        self.assertTrue(doc[\"steps\"][0].startswith(\"open-app\"))\n        self.assertIn(\"WINWORD.EXE\", doc[\"steps\"][0])\n\n    def test_plumbing_is_not_part_of_the_story(self):\n        doc = history.summarise(self.entries(), \"abcd\")\n        self.assertFalse(any(\"session.start\" in s for s in doc[\"steps\"]))\n\n    def test_produced_files_are_remembered(self):\n        doc = history.summarise(self.entries(), \"abcd\")\n        self.assertIn(\"C:/out/report.docx\", doc[\"artifacts\"])\n\n    def test_failures_are_kept_because_they_are_the_useful_part(self):\n        doc = history.summarise(self.entries(), \"abcd\")\n        self.assertEqual(doc[\"errors\"][0][\"verb\"], \"browser.navigate\")\n\n    def test_url_query_state_is_not_carried_into_history(self):\n        \"\"\"Enterprise links carry live session state; history outlives it.\"\"\"\n        doc = history.summarise(self.entries(), \"abcd\")\n        blob = json.dumps(doc)\n        self.assertNotIn(\"token=secret\", blob)\n        self.assertIn(\"example.com/a\", blob)\n\n    def test_a_session_that_did_nothing_is_not_recorded(self):\n        home = Path(tempfile.mkdtemp())\n        got = history.record(home, \"aaaa\", [\n            {\"ts\": \"t\", \"method\": \"session.start\", \"outcome\": \"ok\"},\n            {\"ts\": \"t\", \"method\": \"system.ping\", \"outcome\": \"ok\"}])\n        self.assertIsNone(got)\n\n    def test_a_record_stays_small(self):\n        home = Path(tempfile.mkdtemp())\n        many = [{\"ts\": \"2026-01-01T10:00:00\", \"method\": \"desktop.click\",\n                 \"outcome\": \"ok\", \"params\": {\"ref\": f\"@e{i}\"}}\n                for i in range(500)]\n        path = history.record(home, \"bbbb\", many)\n        self.assertIsNotNone(path)\n        self.assertLess(path.stat().st_size, 8 * 1024)\n\n    def test_long_runs_are_elided_in_the_middle_not_truncated_at_the_end(self):\n        doc = history.summarise(\n            [{\"ts\": \"t\", \"method\": \"desktop.click\", \"outcome\": \"ok\",\n              \"params\": {\"ref\": f\"@e{i}\"}} for i in range(500)], \"cccc\")\n        self.assertTrue(any(\"more steps\" in s for s in doc[\"steps\"]))\n        self.assertIn(\"@e499\", doc[\"steps\"][-1])\n\n    def test_records_are_listed_shown_and_forgotten(self):\n        home = Path(tempfile.mkdtemp())\n        path = history.record(home, \"dddd\", self.entries())\n        listing = history.list_records(home)\n        self.assertEqual(listing[\"count\"], 1)\n        shown = history.show_record(home, path.stem)\n        self.assertEqual(shown[\"session\"], \"dddd\")\n        by_session = history.show_record(home, \"dddd\")\n        self.assertEqual(by_session[\"id\"], path.stem)\n        history.forget(home, path.stem)\n        self.assertEqual(history.list_records(home)[\"count\"], 0)\n\n    def test_an_unknown_record_says_how_to_find_the_real_ones(self):\n        with self.assertRaises(ProtocolError) as ctx:\n            history.show_record(Path(tempfile.mkdtemp()), \"nope\")\n        self.assertIn(\"history list\", ctx.exception.error.hint)\n\n    def test_stopping_a_session_records_before_it_clears(self):\n        src = (ROOT / \"src\" / \"autoskill\" / \"daemon.py\").read_text(encoding=\"utf-8\")\n        body = src.split(\"def _stop_session_locked\")[1].split(\"\\n    def \")[0]\n        self.assertLess(body.index(\"from .history import record\"),\n                        body.index(\"s.browser.close()\"))\n\n    def test_history_tools_are_exposed_and_reads_are_free(self):\n        names = {t[\"name\"] for t in toolspec.TOOLS}\n        self.assertIn(\"history_list\", names)\n        self.assertIn(\"history_show\", names)\n        self.assertIs(VERB_RISK[\"history.list\"], Risk.READ)\n        self.assertIs(VERB_RISK[\"history.forget\"], Risk.DESTRUCTIVE)\n\n\n\nclass TestCleanStop(unittest.TestCase):\n    \"\"\"`stop` must actually stop - and must never cut a decision in half.\n\n    Written because a stopped run was measured carrying on: its journal grew\n    from 9 entries to 13 after the user asked it to stop, and it had to be\n    killed by PID. On a dry run that is untidy; on a live run it means real\n    approvals kept being made after \"stop\".\n    \"\"\"\n\n    def runner(self, **kw):\n        from autoskill.workflow import FlowRunner\n        home = Path(tempfile.mkdtemp())\n        return FlowRunner(_profile(), home=home, on_event=lambda *_: None, **kw)\n\n    def setUp(self):\n        from autoskill import workflow\n        workflow._SIGNALLED.clear()\n\n    tearDown = setUp\n\n    def test_a_stop_file_is_seen_and_says_who_asked(self):\n        r = self.runner()\n        self.assertIsNone(r.stop_requested())\n        r.stop_file.write_text(\"asked to stop from the command line\",\n                               encoding=\"utf-8\")\n        self.assertIn(\"command line\", r.stop_requested() or \"\")\n\n    def test_a_signal_is_honoured_without_raising_mid_click(self):\n        \"\"\"The handler only sets a flag. Raising KeyboardInterrupt where the\n        run happens to be could land between an irreversible click and the\n        journal line recording it.\"\"\"\n        from autoskill import workflow\n        r = self.runner()\n        workflow.request_stop_via_signal(\"SIGINT\")\n        self.assertIn(\"SIGINT\", r.stop_requested() or \"\")\n\n    def test_a_stale_stop_does_not_kill_the_next_run(self):\n        \"\"\"Otherwise yesterday's stop file silently ends today's run before\n        it reads a single row, which looks exactly like a hang.\"\"\"\n        r = self.runner()\n        r.stop_file.write_text(\"old\", encoding=\"utf-8\")\n        r.clear_stop()\n        self.assertFalse(r.stop_file.exists())\n        self.assertIsNone(r.stop_requested())\n\n    def test_the_loop_stops_before_picking_up_new_work(self):\n        from autoskill import workflow\n        r = self.runner()\n        calls = []\n\n        def fake_call(verb, params=None, timeout=120):\n            calls.append(verb)\n            workflow.request_stop_via_signal(\"SIGINT\")   # arrives mid-pass\n            return {\"tabs\": []}\n\n        r.call = fake_call\n        real_sleep = workflow.time.sleep\n        workflow.time.sleep = lambda *_a: None\n        try:\n            out = r.run(minutes=1)\n        finally:\n            workflow.time.sleep = real_sleep\n\n        self.assertEqual(calls, [\"tabs\"])          # did not start a 2nd pass\n        self.assertIn(\"SIGINT\", out.get(\"stopped\") or \"\")\n        self.assertEqual(out[\"examined\"], 0)\n        self.assertEqual(out[\"acted\"], 0)\n\n    def test_a_stop_is_checked_before_the_commit_sequence_begins(self):\n        src = (ROOT / \"src\" / \"autoskill\" / \"workflow.py\").read_text(\n            encoding=\"utf-8\")\n        body = src.split(\"def run(self\")[1]\n        self.assertLess(body.index(\"stop_requested()\"),\n                        body.index(\"self._execute(\"))\n\n    def test_a_stop_never_lands_inside_a_commit_sequence(self):\n        \"\"\"Once the sequence has begun, stopping could leave an approval\n        half-entered. The bound is one item, not one run - so `_execute`\n        itself must not consult the stop.\"\"\"\n        src = (ROOT / \"src\" / \"autoskill\" / \"workflow.py\").read_text(\n            encoding=\"utf-8\")\n        execute = src.split(\"def _execute\")[1].split(\"\\n    def \")[0]\n        self.assertNotIn(\"stop_requested\", execute)\n\n    def test_the_action_budget_bounds_irreversible_steps_not_reads(self):\n        \"\"\"`--max-items` bounds rows READ. On a live run the number that\n        matters is rows ACTED ON, because only that part cannot be undone.\"\"\"\n        src = (ROOT / \"src\" / \"autoskill\" / \"workflow.py\").read_text(\n            encoding=\"utf-8\")\n        run = src.split(\"def run(self\")[1].split(\"\\n    def \")[0]\n        self.assertIn(\"max_acted\", run)\n        # bound checked BEFORE a new item is opened, and again right after\n        # acting, so it binds immediately instead of one item late\n        self.assertGreaterEqual(run.count(\"acted >= max_acted\"), 2)\n\n    def test_the_budget_ends_the_run_with_a_stated_reason(self):\n        from autoskill import workflow\n        r = self.runner()\n        r.call = lambda *a, **k: {\"tabs\": []}\n        real_sleep = workflow.time.sleep\n        workflow.time.sleep = lambda *_a: None\n        try:\n            out = r.run(minutes=1, max_acted=1)\n        finally:\n            workflow.time.sleep = real_sleep\n        self.assertIn(\"stopped\", out)\n\n    def test_the_run_reports_why_it_ended(self):\n        r = self.runner()\n        out = r.run(minutes=0)          # deadline already passed\n        self.assertIn(\"stopped\", out)\n\n\nclass TestReachabilityIsNotVisibility(unittest.TestCase):\n    \"\"\"Found live: a run opened nothing while the observation held 259 rows.\n\n    They sat inside a collapsed panel - in the accessibility tree, invisible\n    to a click. `reach_list` fires only when the item pattern matches\n    NOTHING, so a full row count convinced the engine it was already on the\n    list, and the stale-state reload returned to the landing screen and\n    collapsed the panel again, making the condition permanent.\n    \"\"\"\n\n    def test_repeated_dead_clicks_trigger_a_re_navigation(self):\n        src = (ROOT / \"src\" / \"autoskill\" / \"workflow.py\").read_text(\n            encoding=\"utf-8\")\n        run = src.split(\"def run(self\")[1].split(\"\\n    def \")[0]\n        heal = run.split(\"no work tab appeared\")[1]\n        self.assertIn(\"force_reach = True\", heal)\n\n    def test_the_heal_re_navigates_rather_than_only_reloading(self):\n        \"\"\"A reload alone was not merely insufficient, it was the trap: it\n        returns to the landing screen, where the list is collapsed.\"\"\"\n        src = (ROOT / \"src\" / \"autoskill\" / \"workflow.py\").read_text(\n            encoding=\"utf-8\")\n        run = src.split(\"def run(self\")[1].split(\"\\n    def \")[0]\n        self.assertIn(\"if force_reach:\", run)\n        self.assertLess(run.index(\"if force_reach:\"),\n                        run.index(\"items = re.findall(self.p.item, body)\"))\n\n    def test_the_engine_still_names_no_site(self):\n        \"\"\"The heal must not smuggle in knowledge of a particular page.\"\"\"\n        import ast as _ast\n        src = (ROOT / \"src\" / \"autoskill\" / \"workflow.py\").read_text(\n            encoding=\"utf-8\")\n        # Read the CODE, not the prose. Comments and docstrings discuss the\n        # pages these bugs were found on - naming one there is documentation,\n        # not a dependency. An earlier version lower-cased the whole file and\n        # tripped over a comment explaining why a double approval must be\n        # impossible.\n        tree = _ast.parse(src)\n        for node in _ast.walk(tree):\n            if (isinstance(node, _ast.Expr)\n                    and isinstance(node.value, _ast.Constant)\n                    and isinstance(node.value.value, str)):\n                node.value.value = \"\"\n        code = _ast.unparse(tree).lower()\n        for word in (\"notification\", \"oracle\", \"show all\", \"worklist\",\n                     \"claim\", \"approve\"):\n            self.assertNotIn(word, code, f\"engine names {word!r}\")\n\n\nclass TestAFailedItemDoesNotBlockTheQueue(unittest.TestCase):\n    \"\"\"Measured live: the same row reopened until the clock ran out.\n\n        [4/199] opening @e23 ... sequence stopped\n        [4/199] opening @e23 ... sequence stopped\n\n    The cursor holds after a SUCCESSFUL action because an actioned row leaves\n    the queue and the rest shift up. A failed row is still there, so holding\n    meant nothing behind it was ever reached. Most failures on a shared\n    worklist are simply items assigned to someone else: their Claim control\n    is present but inert, so the Approve the sequence waits for never comes.\n    \"\"\"\n\n    def run_src(self):\n        src = (ROOT / \"src\" / \"autoskill\" / \"workflow.py\").read_text(\n            encoding=\"utf-8\")\n        return src.split(\"def run(self\")[1].split(\"\\n    def \")[0]\n\n    def test_the_cursor_advances_when_the_action_did_not_succeed(self):\n        tail = self.run_src().split(\"ok = self._execute(\")[1]\n        self.assertIn(\"if not ok:\", tail)\n        self.assertLess(tail.index(\"if not ok:\"), tail.index(\"time.sleep(3)\"))\n\n    def test_the_cursor_still_holds_after_a_successful_action(self):\n        \"\"\"An actioned row leaves the queue, so advancing would skip its\n        replacement - the original reason the cursor stays put.\"\"\"\n        tail = self.run_src().split(\"ok = self._execute(\")[1]\n        guarded = tail.split(\"if not ok:\")[1].split(\"continue\")[0]\n        self.assertIn(\"pos += 1\", guarded)\n\n    def test_a_failure_is_still_recorded_as_a_failure(self):\n        \"\"\"Advancing past it must not quietly turn it into a decision, or a\n        later run would never retry an item that was merely unavailable.\"\"\"\n        src = (ROOT / \"src\" / \"autoskill\" / \"workflow.py\").read_text(\n            encoding=\"utf-8\")\n        execute = src.split(\"def _execute\")[1].split(\"\\n    def \")[0]\n        self.assertIn('action=\"failed\"', execute)\n\n\nclass TestAnActionedItemIsNotRetriedInTheSameRun(unittest.TestCase):\n    \"\"\"Measured live - a second irreversible sequence on the same item:\n\n        [4/199] ACTED on ... Emirates ID [60bd10a5]\n        [4/199] opening @e23\n                ACTING on ... Emirates ID [60bd10a5]\n                sequence stopped\n\n    Nothing was double-approved only because the site had already withdrawn\n    its Approve control. The safety came from the page, not the tool, which\n    is the wrong place for it. Every other outcome updated the in-memory\n    `decided` set - a skip did, a dry run did - and the one case where a\n    repeat is actually harmful did not.\n    \"\"\"\n\n    def run_src(self):\n        src = (ROOT / \"src\" / \"autoskill\" / \"workflow.py\").read_text(\n            encoding=\"utf-8\")\n        return src.split(\"def run(self\")[1].split(\"\\n    def \")[0]\n\n    def test_a_successful_action_is_remembered_before_the_next_pass(self):\n        tail = self.run_src().split(\"ok = self._execute(\")[1]\n        self.assertIn(\"decided.add(identity)\", tail)\n\n    def test_it_is_remembered_only_when_the_action_succeeded(self):\n        \"\"\"A failed item was merely unavailable; a later run must retry it.\"\"\"\n        tail = self.run_src().split(\"ok = self._execute(\")[1]\n        guard = tail.split(\"decided.add(identity)\")[0]\n        self.assertIn(\"if ok and identity:\", guard)\n\n    def test_every_outcome_updates_the_decided_set(self):\n        \"\"\"skip, dry-run and act all end an item's life in this run.\"\"\"\n        run = self.run_src()\n        self.assertGreaterEqual(run.count(\"decided.add(identity)\"), 3)\n\n\nclass TestAStepMustProveItTookEffect(unittest.TestCase):\n    \"\"\"The actionability probe, one level up.\n\n    The probe answers \"can this click reach the element?\". It cannot answer\n    \"did the click change anything?\" — and on a shared worklist that is the\n    question that decides everything. Measured: three consecutive requests\n    whose Claim button was present, was clicked successfully, and did\n    nothing; each was `Assigned to` a group of ten other approvers. The run\n    waited 45s for an Approve that could never appear, and recorded `failed`\n    for an item that was simply not ours.\n    \"\"\"\n\n    def wf(self):\n        return (ROOT / \"src\" / \"autoskill\" / \"workflow.py\").read_text(\n            encoding=\"utf-8\")\n\n    def test_a_step_can_declare_the_evidence_that_it_worked(self):\n        src = self.wf()\n        step = src.split(\"class Step\")[1].split(\"@dataclass\")[0]\n        self.assertIn(\"proves\", step)\n\n    def test_the_evidence_is_checked_straight_after_the_step(self):\n        ex = self.wf().split(\"def _execute\")[1].split(\"\\n    def \")[0]\n        self.assertIn(\"_evidence_missing\", ex)\n\n    def test_no_effect_is_retryable_not_a_decision(self):\n        \"\"\"Reversed in S135. This test used to demand `skipped`, and in doing\n        so encoded F-21 as intended behaviour: a Claim judged by one look 2s\n        after the click - it takes ~18s - retired 20 claimable requests for\n        ever. \"The control is still there\" cannot tell \"not ours\" from \"the\n        click did not land\" (118 dead clicks in one day, O-02), so it is\n        `failed`: retryable, not in `decided()`, and no ledger row.\"\"\"\n        ex = self.wf().split(\"def _execute\")[1].split(\"\\n    def \")[0]\n        handler = ex.split(\"except _NoEffect\")[1].split(\"return 0\")[0]\n        self.assertIn('action=\"failed\"', handler)\n        self.assertNotIn('action=\"skipped\"', handler)\n        self.assertNotIn(\"ledger_row\", handler)\n\n    def test_it_is_distinct_from_a_protocol_error(self):\n        \"\"\"Nothing malfunctioned, so it must not travel as an error.\"\"\"\n        src = self.wf()\n        self.assertIn(\"class _NoEffect(Exception)\", src)\n\n    def test_the_engine_still_names_no_site(self):\n        \"\"\"The profile says what the evidence is; the engine only checks it.\"\"\"\n        import ast as _ast\n        tree = _ast.parse(self.wf())\n        for node in _ast.walk(tree):\n            if (isinstance(node, _ast.Expr)\n                    and isinstance(node.value, _ast.Constant)\n                    and isinstance(node.value.value, str)):\n                node.value.value = \"\"\n        code = _ast.unparse(tree).lower()\n        for word in (\"claim\", \"assigned to\", \"oracle\", \"approve\"):\n            self.assertNotIn(word, code, f\"engine names {word!r}\")\n\n\nclass TestRulesFromTheSecondSweep(unittest.TestCase):\n    \"\"\"Swept with the graph rather than waiting for the next live failure.\n\n    Each rule here was broken at more than one site, and in every case the\n    first site had already been fixed in isolation — which is precisely the\n    habit these tests exist to make impossible.\n    \"\"\"\n\n    def wf(self):\n        return (ROOT / \"src\" / \"autoskill\" / \"workflow.py\").read_text(\n            encoding=\"utf-8\")\n\n    def run_src(self):\n        return self.wf().split(\"def run(self\")[1].split(\"\\n    def \")[0]\n\n    # --- a reload lands on the landing screen ----------------------------\n    def test_every_reload_goes_through_the_helper(self):\n        \"\"\"S137: two helpers, one per kind of tab. A LIST tab goes home\n        (`reload_list`) because its URL carries the stale state; an ITEM tab\n        reloads its own URL (`reload_item`), which names the task and repairs\n        a wedged toolbar. No bare reload anywhere else, and the item helper\n        is never pointed at the list.\"\"\"\n        src = self.wf()\n        helper = src.split(\"def reload_list\")[1].split(\"\\n    def \")[0]\n        item = src.split(\"def reload_item\")[1].split(\"\\n    def \")[0]\n        rest = src.replace(helper, \"\").replace(item, \"\")\n        self.assertNotIn('self.call(\"reload\"', rest)\n        self.assertNotIn(\"reload_item(main\", src)\n\n    def test_every_reload_is_followed_by_a_re_navigation(self):\n        \"\"\"A reload returns the tab to its URL - the landing screen, not the\n        list. Two of three reloads forgot, so each undid itself: 21 self-heal\n        cycles in one measured run.\"\"\"\n        import re as _re\n        run = self.run_src()\n        for m in _re.finditer(r\"self\\.reload_list\\(main\\)\", run):\n            after = run[m.end():m.end() + 400]\n            self.assertIn(\"force_reach = True\", after,\n                          \"a reload does not re-reach the list\")\n\n    # --- the irreversible step must be confirmed -------------------------\n    def test_acted_is_never_written_before_the_evidence_is_checked(self):\n        \"\"\"The Claim fault, on the one step that cannot be taken back: a\n        swallowed Submit would be journalled as an approval that never\n        happened, and `decided` would close the item for ever.\"\"\"\n        ex = self.wf().split(\"def _execute\")[1].split(\"\\n    def \")[0]\n        commit = ex.split(\"if step.commit:\")[-1]\n        # Spelled through the shared helper since the three runners were\n        # unified; the rule is unchanged - confirm, then claim.\n        self.assertLess(commit.index(\"_evidence_missing\"),\n                        commit.index('action=\"acted\"'))\n\n    def test_an_unconfirmed_commit_is_neither_acted_nor_failed(self):\n        \"\"\"`failed` asserts nothing happened; `acted` asserts it did.\n        Neither is known. A `committing` with no `acted` is the honest\n        unknown the journal already models, and `decided()` counts it.\"\"\"\n        ex = self.wf().split(\"def _execute\")[1].split(\"\\n    def \")[0]\n        handler = ex.split(\"except _Unconfirmed\")[1].split(\"except \")[0]\n        self.assertNotIn('action=\"acted\"', handler)\n        self.assertNotIn('action=\"failed\"', handler)\n        self.assertIn(\"UNCONFIRMED\", handler)\n\n    def test_unconfirmed_is_a_distinct_outcome(self):\n        self.assertIn(\"class _Unconfirmed(Exception)\", self.wf())\n\n    # --- evidence where it was measured; the next wait everywhere else ---\n    # Replaced in S135. `test_every_clicking_step_declares_its_evidence`\n    # demanded `proves` on Claim and Approve and so defended F-21: the\n    # evidence it required was a snapshot that fired falsely on 20 claimable\n    # requests and on both requests of the T2 run.\n    def _oracle(self):\n        import json as _json\n        return _json.loads(\n            (ROOT / \"skill\" / \"profiles\" / \"oracle-cpi.json\").read_text(\n                encoding=\"utf-8\"))\n\n    def test_the_irreversible_step_declares_its_evidence(self):\n        \"\"\"`acted` is written only once the commit is confirmed.\"\"\"\n        commit = [s for s in self._oracle()[\"steps\"] if s.get(\"commit\")]\n        self.assertEqual(len(commit), 1)\n        self.assertTrue(commit[0].get(\"proves\"))\n\n    def test_every_other_click_is_proved_by_the_wait_that_follows_it(self):\n        \"\"\"Claim is proved by Approve appearing, Approve by Submit appearing:\n        a bounded wait for what must come next, measured to work in T4.\n        A click with neither is a failure discovered only by a later\n        timeout.\"\"\"\n        steps = self._oracle()[\"steps\"]\n        for i, st in enumerate(steps):\n            if st.get(\"do\") != \"click\" or st.get(\"commit\"):\n                continue\n            later = [s.get(\"do\") for s in steps[i + 1:]]\n            self.assertTrue(st.get(\"proves\") or \"wait\" in later,\n                            f\"step {i} {st.get('match')!r} has no evidence\")\n\n    def test_a_step_without_evidence_says_why(self):\n        \"\"\"So nobody restores the snapshot check without its measurements.\"\"\"\n        for st in self._oracle()[\"steps\"]:\n            if st.get(\"do\") == \"click\" and not st.get(\"proves\"):\n                self.assertIn(\"_no_evidence\", st)\n\n\nclass TestEvidenceIsCheckedInOnePlace(unittest.TestCase):\n    \"\"\"Three sequence runners needed evidence checking and one had it.\n\n    Measured on a 15-approval run that stalled: five reach sequences, six\n    dead clicks, no progress. A screenshot settled it at once — the page was\n    still on the Notifications view with the Worklist button visible and\n    unclicked. `_run_steps` ignored `proves` entirely, and its optional steps\n    skip silently, so a navigation sequence completed \"successfully\" without\n    leaving the page it existed to leave.\n    \"\"\"\n\n    def wf(self):\n        return (ROOT / \"src\" / \"autoskill\" / \"workflow.py\").read_text(\n            encoding=\"utf-8\")\n\n    def test_there_is_exactly_one_evidence_check(self):\n        \"\"\"Two copies of this question drift; three definitely do.\"\"\"\n        src = self.wf()\n        self.assertIn(\"def _evidence_missing\", src)\n        # the regex test lives only inside the helper\n        helper = src.split(\"def _evidence_missing\")[1].split(\"\\n    def \")[0]\n        outside = src.replace(helper, \"\")\n        self.assertNotIn(\"re.search(step.proves\", outside)\n\n    def test_every_sequence_runner_uses_it(self):\n        src = self.wf()\n        for runner in (\"_run_steps\", \"_execute\"):\n            body = src.split(f\"def {runner}(\")[1].split(\"\\n    def \")[0]\n            self.assertIn(\"_evidence_missing\", body,\n                          f\"{runner} runs steps without checking evidence\")\n\n    def test_a_navigation_step_that_did_nothing_stops_the_sequence(self):\n        \"\"\"Later steps depend on it; carrying on only hides the cause.\"\"\"\n        body = self.wf().split(\"def _run_steps(\")[1].split(\"\\n    def \")[0]\n        after = body.split(\"_evidence_missing\")[1]\n        self.assertIn(\"return\", after.split(\"body = self.observe(tab)\")[0])\n\n    def test_the_reach_waits_for_its_control_instead_of_racing_it(self):\n        \"\"\"The step was optional and raced the page: unmatched within 3s it\n        was skipped silently and the sequence reported success.\"\"\"\n        import json as _json\n        prof = _json.loads(\n            (ROOT / \"skill\" / \"profiles\" / \"oracle-cpi.json\").read_text(\n                encoding=\"utf-8\"))\n        kinds = [s.get(\"do\") for s in prof[\"list\"][\"reach\"]]\n        self.assertIn(\"wait\", kinds, \"the reach sequence still races the page\")\n\n    def test_a_step_declares_evidence_only_where_it_was_measured(self):\n        \"\"\"Retired the demand that every reach step prove itself.\n\n        Measurement killed that premise: the Worklist button does NOT vanish\n        when the Worklist opens — it is a permanent header control — and the\n        two views are indistinguishable in the accessibility tree. A `proves`\n        there turned a succeeding step into a reported failure and stopped\n        the run, which is the fault it was meant to prevent, inverted.\n\n        The rule that survives: declare evidence you have measured, or state\n        plainly why there is none. Enforced by\n        `TestTransientVersusDecided.test_no_reach_step_claims_evidence_...`.\n        \"\"\"\n        import json as _json\n        prof = _json.loads(\n            (ROOT / \"skill\" / \"profiles\" / \"oracle-cpi.json\").read_text(\n                encoding=\"utf-8\"))\n        for st in prof[\"list\"][\"reach\"] + prof[\"steps\"]:\n            if st.get(\"proves\"):\n                self.assertTrue(st.get(\"proves_label\"),\n                                \"evidence with no label cannot be reported\")\n\n\nclass TestTransientVersusDecided(unittest.TestCase):\n    \"\"\"An unreadable page is not a decision about the request.\n\n    Measured live: `INCOMPLETE READ - not classified` was journalled as\n    `skipped` and added to `decided`, retiring the request for ever without\n    it ever being judged. The complete gate is fail-closed by design and\n    right to refuse — but its refusal says \"I could not read this\", not\n    \"this one is excluded\".\n    \"\"\"\n\n    def run_src(self):\n        src = (ROOT / \"src\" / \"autoskill\" / \"workflow.py\").read_text(\n            encoding=\"utf-8\")\n        return src.split(\"def run(self\")[1].split(\"\\n    def \")[0]\n\n    def seg(self):\n        return self.run_src().split('if v.outcome != \"act\":')[1][:1400]\n\n    def test_an_incomplete_read_is_recorded_as_retryable(self):\n        seg = self.seg()\n        self.assertIn('v.outcome == \"incomplete\"', seg)\n        self.assertIn('action=\"failed\" if transient else \"skipped\"', seg)\n\n    def test_an_incomplete_read_is_not_added_to_decided(self):\n        \"\"\"`decided()` deliberately does not count `failed`, so the item\n        stays eligible for a later run.\"\"\"\n        guarded = self.seg().split(\"if not transient:\")[1][:300]\n        self.assertIn(\"decided.add(identity)\", guarded)\n\n    def test_a_real_exclusion_is_still_a_decision(self):\n        \"\"\"A family/child update is a fact read from the page and must not\n        be revisited for ever. (Assigned-to-someone-else used to be listed\n        here too; since S135 it is retryable, because the only evidence for\n        it was a control that had not yet disappeared.)\"\"\"\n        guarded = self.seg().split(\"if not transient:\")[1][:300]\n        self.assertIn(\"ledger_row\", guarded)\n\n    def test_no_reach_step_claims_evidence_that_was_never_measured(self):\n        \"\"\"I declared the Worklist button must vanish once the Worklist\n        opens. It does not — it is a permanent header control, and the two\n        views cannot be told apart in the accessibility tree at all. The\n        check turned a succeeding step into a reported failure. Evidence\n        you have not measured is worse than none.\"\"\"\n        # Rewritten in S135 (CM-01): the old body only looked at steps whose\n        # match named \"Worklist\", a step the profile no longer has, so the\n        # loop never asserted anything and the test passed vacuously. The\n        # rule now holds for every reach step: evidence only with the\n        # measurement that justifies it.\n        import json as _json\n        prof = _json.loads(\n            (ROOT / \"skill\" / \"profiles\" / \"oracle-cpi.json\").read_text(\n                encoding=\"utf-8\"))\n        reach = prof[\"list\"][\"reach\"]\n        self.assertTrue(reach, \"the profile has no reach sequence to check\")\n        for i, st in enumerate(reach):\n            if st.get(\"proves\"):\n                self.assertIn(\"_proves_evidence\", st,\n                              f\"reach step {i} declares evidence nobody \"\n                              f\"measured\")\n\n    def test_the_reach_still_waits_instead_of_racing(self):\n        \"\"\"The race was real and its fix stays: an optional step skipped\n        silently when the control had not rendered within 3s.\"\"\"\n        import json as _json\n        prof = _json.loads(\n            (ROOT / \"skill\" / \"profiles\" / \"oracle-cpi.json\").read_text(\n                encoding=\"utf-8\"))\n        self.assertIn(\"wait\", [s.get(\"do\") for s in prof[\"list\"][\"reach\"]])\n\n\nclass TestNoSequenceMatchesAStalePage(unittest.TestCase):\n    \"\"\"The cause of every dead click across three runs.\n\n    A ref is only valid for the observation that issued it, and refs are\n    re-issued on every observation. So a stale ref is worse than a missing\n    one: it can resolve to a *different* element. The click lands, the\n    actionability probe is satisfied, the caller is told it worked — and\n    something else was pressed. That is how a diagnostic click on a\n    \"harmless\" element navigated the whole page earlier in this session.\n\n    Measured: clicking the same row by a freshly read backend id opened its\n    work tab immediately, every time. The rows were never the problem.\n    \"\"\"\n\n    def wf(self):\n        return (ROOT / \"src\" / \"autoskill\" / \"workflow.py\").read_text(\n            encoding=\"utf-8\")\n\n    def test_a_sequence_returns_the_settled_page_not_the_mid_flight_one(self):\n        \"\"\"Sequences end with a settle, and only clicks and types re-read —\n        so the body returned described the page mid-navigation.\"\"\"\n        body = self.wf().split(\"def _run_steps(\")[1].split(\"\\n    def \")[0]\n        tail = body.split(\"for step in steps:\")[1]\n        # The sequence's own return, not the except-fallback beneath it.\n        self.assertIn(\"return self.observe(tab)\", tail)\n\n    def test_the_acting_sequence_re_reads_after_every_step(self):\n        \"\"\"Each step used to match against the page as it was BEFORE the\n        previous step changed it.\"\"\"\n        ex = self.wf().split(\"def _execute\")[1].split(\"\\n    def \")[0]\n        lines = ex.splitlines()\n        pressed = 0\n        for i, l in enumerate(lines):\n            # S139: the ladder branch presses too, and must re-read as well.\n            if ('self.call(\"click\"' in l or 'self.call(\"type\"' in l\n                    or \"self._press_ladder(\" in l or \"self._press_near(\" in l):\n                pressed += 1\n                # a wide window: the reason for the re-read is long\n                window = \"\\n\".join(lines[i:i + 24])\n                self.assertIn(\"body = self.observe\", window,\n                              \"a step acts and the next matches a stale page\")\n        self.assertGreaterEqual(pressed, 4, \"the rule found nothing to check\")\n\n    def test_the_patient_re_read_is_not_relied_on_as_the_guard(self):\n        \"\"\"It fires only when the pattern does NOT match — which is exactly\n        backwards, because a stale body usually does match: the old control\n        is still in the old text.\"\"\"\n        ex = self.wf().split(\"def _execute\")[1].split(\"\\n    def \")[0]\n        # the refresh must come before the fallback can matter\n        self.assertLess(ex.index(\"body = self.observe(tab)\"),\n                        ex.rindex(\"one patient re-read\"))\n\n\nclass TestEvidenceIsWaitedForNotGlanced(unittest.TestCase):\n    \"\"\"S135: the F-21 class, tested by running the engine, not by reading it.\n\n    The evidence check slept 2s and looked once. A Claim takes ~18s, so a\n    claimable request was judged \"no effect\" and journalled `skipped`, which\n    retired it for ever: 20 requests, and both requests of the T2 run. The\n    class is \"a snapshot at a fixed moment turned into a permanent decision\";\n    these tests pin both halves of the fix.\n    \"\"\"\n\n    def setUp(self):\n        import autoskill.workflow as wf\n        self.wf = wf\n        self._poll = wf.EVIDENCE_POLL_S\n        wf.EVIDENCE_POLL_S = 0          # poll as fast as the fake page allows\n\n    def tearDown(self):\n        self.wf.EVIDENCE_POLL_S = self._poll\n\n    def runner(self, steps):\n        from autoskill.workflow import FlowRunner\n        r = FlowRunner(_profile(steps=steps), home=Path(tempfile.mkdtemp()),\n                       on_event=lambda *_: None)\n        r.ledger_rows = []\n        r.ledger_row = lambda *a: r.ledger_rows.append(a) or True\n        r.call = lambda *a, **k: {}\n        return r\n\n    @staticmethod\n    def page(*bodies):\n        \"\"\"A tab whose observations change over time: one body per look,\n        the last one repeated.\"\"\"\n        seq = list(bodies)\n\n        def observe(tab, max_tokens=None):\n            return seq.pop(0) if len(seq) > 1 else seq[0]\n        return observe\n\n    GO = '@e1 button \"Go\"'\n    TAKE = '@e2 button \"Take\"'\n\n    def step(self, **kw):\n        from autoskill.workflow import Step\n        return Step(kind=\"click\", pattern=r'(@e\\d+) button \"Take\"',\n                    proves=r'(@e\\d+) button \"Take\"', **kw)\n\n    def test_a_slow_effect_within_the_budget_is_not_missing(self):\n        \"\"\"The F-21 case: the control goes on the third look, not the first.\"\"\"\n        r = self.runner([{\"do\": \"click\", \"match\": r'(@e\\d+) button \"Go\"',\n                          \"commit\": True, \"proves\": r'(@e\\d+) button \"Go\"'}])\n        r.observe = self.page(self.TAKE, self.TAKE, \"done\")\n        self.assertEqual(r._evidence_missing(\"t\", self.step(proves_within=5)), \"\")\n\n    def test_an_effect_that_never_shows_is_missing_after_the_budget(self):\n        r = self.runner([{\"do\": \"click\", \"match\": r'(@e\\d+) button \"Go\"',\n                          \"commit\": True, \"proves\": r'(@e\\d+) button \"Go\"'}])\n        r.observe = self.page(self.TAKE)\n        why = r._evidence_missing(\"t\", self.step(proves_within=0.05))\n        self.assertIn(\"still there after\", why)\n\n    def test_a_tab_that_went_away_proves_the_step_did_something(self):\n        r = self.runner([{\"do\": \"click\", \"match\": r'(@e\\d+) button \"Go\"',\n                          \"commit\": True, \"proves\": r'(@e\\d+) button \"Go\"'}])\n\n        def gone(tab, max_tokens=None):\n            raise ProtocolError(__import__(\"autoskill.protocol\").protocol\n                                .ErrorCode.TARGET_NOT_FOUND, \"tab closed\")\n        r.observe = gone\n        self.assertEqual(r._evidence_missing(\"t\", self.step(proves_within=1)), \"\")\n\n    def test_no_effect_in_a_real_run_is_retryable_and_not_ledgered(self):\n        \"\"\"End to end through `_execute`: a non-commit step whose control\n        never goes leaves the item `failed` - not decided, no ledger row.\"\"\"\n        from autoskill.workflow import Verdict\n        steps = [{\"do\": \"click\", \"match\": r'(@e\\d+) button \"Take\"',\n                  \"proves\": r'(@e\\d+) button \"Take\"', \"proves_within\": 0.05},\n                 {\"do\": \"click\", \"match\": r'(@e\\d+) button \"Go\"',\n                  \"commit\": True, \"proves\": r'(@e\\d+) button \"Go\"'}]\n        r = self.runner(steps)\n        r.observe = self.page(self.TAKE + \"\\n\" + self.GO)\n        ok = r._execute(\"t\", self.TAKE + \"\\n\" + self.GO, \"id-1\",\n                        Verdict(\"act\", \"Refund\"), \"Refund\", \"S\")\n        self.assertEqual(ok, 0)\n        self.assertNotIn(\"id-1\", r.decided())\n        self.assertEqual(r.ledger_rows, [])\n        rows = r.journal_rows()\n        self.assertEqual(rows[-1][\"action\"], \"failed\")\n        self.assertEqual(rows[-1][\"verdict\"], \"no-effect\")\n        self.assertFalse([x for x in rows if x.get(\"action\") == \"committing\"],\n                         \"the irreversible step must not be reached\")\n\n    def test_a_confirmed_commit_is_acted_and_decided(self):\n        from autoskill.workflow import Verdict\n        r = self.runner([{\"do\": \"click\", \"match\": r'(@e\\d+) button \"Go\"',\n                          \"commit\": True, \"proves\": r'(@e\\d+) button \"Go\"',\n                          \"proves_within\": 5}])\n        r.observe = self.page(self.GO, self.GO, \"submitted\")\n        ok = r._execute(\"t\", self.GO, \"id-2\", Verdict(\"act\", \"Refund\"),\n                        \"Refund\", \"S\")\n        self.assertEqual(ok, 1)\n        self.assertIn(\"id-2\", r.decided())\n        self.assertEqual([x[\"action\"] for x in r.journal_rows()],\n                         [\"committing\", \"acted\"])\n\n    def test_a_commit_step_without_evidence_is_refused(self):\n        \"\"\"Otherwise `acted` is written the instant the click is sent.\"\"\"\n        with self.assertRaises(ProtocolError) as ctx:\n            _profile(steps=[{\"do\": \"click\", \"match\": r\"(@e\\d+) Go\",\n                             \"commit\": True}])\n        self.assertIn(\"proves\", ctx.exception.error.message)\n\n    def test_the_template_and_the_analyser_draft_obey_the_rule(self):\n        \"\"\"Both are where new profiles come from.\"\"\"\n        from autoskill.workflow import Profile, profiles_dir\n        Profile.load(profiles_dir() / \"TEMPLATE.json\")\n        from autoskill import analyse\n        draft = analyse.suggest_profile(\n            '@e1 link \"Item A\"\\n@e2 link \"Item B\"\\n@e3 link \"Item C\"\\n'\n            '@e9 button \"Approve\"')\n        Profile.from_dict({k: v for k, v in draft.items()\n                           if not k.startswith(\"_\")})\n\n\nclass TestEngineFaultsFromTheLiveTests(unittest.TestCase):\n    \"\"\"S135: F-23, F-24 and F-25, found in the T2/T4 live runs, run for real.\n\n    Each test drives the engine against a fake surface. A test that only\n    reads the source can pass while the behaviour is wrong (CM-18), and the\n    behaviour is what failed live.\n    \"\"\"\n\n    def setUp(self):\n        from unittest import mock\n        self._sleep = mock.patch(\"autoskill.workflow.time.sleep\",\n                                 lambda *_: None)\n        self._sleep.start()\n\n    def tearDown(self):\n        self._sleep.stop()\n\n    # --- F-23 ------------------------------------------------------------\n    def test_a_permanent_block_of_decided_rows_is_walked_past(self):\n        \"\"\"Six decided rows head the queue for good (skipped items are never\n        actioned, so they never leave it). The old heal reloaded and began\n        again at row 1 every time it met five of them - for ever. Now it\n        reloads once, then walks past to the first undecided row.\"\"\"\n        from autoskill.workflow import FlowRunner\n        r = FlowRunner(_profile(), home=Path(tempfile.mkdtemp()),\n                       on_event=lambda *_: None)\n        for i in range(1, 7):\n            r.journal_append(action=\"skipped\", identity=f\"r{i}\", subject=\"S\",\n                             summary=\"Excluded\")\n        rows = \"\\n\".join(f'@e{i} link \"Item {i}\"' for i in range(1, 9))\n        state = {\"work\": None, \"reloads\": 0, \"calls\": 0}\n\n        def call(verb, params=None, timeout=120):\n            state[\"calls\"] += 1\n            if state[\"calls\"] > 400:\n                raise AssertionError(\"the engine is looping\")\n            params = params or {}\n            if verb == \"tabs\":\n                tabs = [{\"tabId\": \"main\", \"url\": \"queue\"}]\n                if state[\"work\"]:\n                    tabs.append({\"tabId\": \"work\",\n                                 \"url\": f\"task?id={state['work']}\"})\n                return {\"tabs\": tabs}\n            if verb == \"observe\":\n                return {\"text\": rows if params.get(\"tab_id\") == \"main\"\n                        else \"unreadable\"}\n            if verb == \"click\" and params.get(\"tab_id\") == \"main\":\n                state[\"work\"] = \"r\" + params[\"ref\"][2:]      # @eN opens rN\n                return {}\n            if verb == \"close\":\n                state[\"work\"] = None\n                return {}\n            if verb in (\"reload\", \"navigate\"):\n                state[\"reloads\"] += 1\n                return {}\n            return {}\n        r.call = call\n        out = r.run(minutes=1, max_items=1)\n        self.assertEqual(out[\"examined\"], 1, \"never reached an undecided row\")\n        self.assertLessEqual(state[\"reloads\"], 1)\n        self.assertIn(\"r7\", [x.get(\"identity\") for x in r.journal_rows()])\n\n    # --- F-24 ------------------------------------------------------------\n    def _reach_runner(self, click_fails):\n        from autoskill.workflow import FlowRunner\n        from autoskill.protocol import ErrorCode\n        p = _profile(list={\"item\": r'(@e\\d+) link \"Item ([^\"]+)\"',\n                           \"identity_param\": \"id\",\n                           \"reach\": [{\"do\": \"click\", \"optional\": True,\n                                      \"match\": r'(@e\\d+) link \"Bell\"'}]})\n        r = FlowRunner(p, home=Path(tempfile.mkdtemp()),\n                       on_event=lambda *_: None)\n        clicks = []\n        state = {\"open\": False}\n\n        def call(verb, params=None, timeout=120):\n            if verb == \"observe\":\n                # the landing page: the bell AND preview rows, always; a\n                # bell press that lands opens the panel over it (a press the\n                # page did not answer is a failure now, F-24)\n                text = self.LANDING\n                if state[\"open\"]:\n                    text += '\\n@e9 link \"Panel: Item B\"'\n                return {\"text\": text}\n            if verb == \"click\":\n                clicks.append(params)\n                if click_fails:\n                    # what the actionability probe says under the overlay\n                    raise ProtocolError(ErrorCode.TARGET_NOT_VISIBLE,\n                                        \"cannot click it: something is on \"\n                                        \"top of it\")\n                state[\"open\"] = True\n            return {}\n        r.call = call\n        return r, clicks\n\n    LANDING = '@e1 link \"Bell\"\\n@e5 link \"Item A\"'\n\n    def test_a_refused_reach_click_is_retried_even_with_rows_on_screen(self):\n        \"\"\"The rows were preview rows; the bell click had been refused under\n        the rQuick overlay. Rows present used to count as success.\"\"\"\n        r, clicks = self._reach_runner(click_fails=True)\n        r.reach_list(\"main\", self.LANDING)\n        self.assertEqual(len(clicks), 2, \"the failed sequence was not retried\")\n\n    def test_a_completed_reach_is_not_repeated(self):\n        r, clicks = self._reach_runner(click_fails=False)\n        r.reach_list(\"main\", self.LANDING)\n        self.assertEqual(len(clicks), 1)\n\n    # --- F-25 ------------------------------------------------------------\n    def _run_cli(self, profile_text):\n        import contextlib\n        import io\n        from autoskill import cli\n        path = Path(tempfile.mkdtemp()) / \"p.json\"\n        path.write_text(profile_text, encoding=\"utf-8\")\n        err = io.StringIO()\n        with contextlib.redirect_stderr(err), \\\n                contextlib.redirect_stdout(io.StringIO()):\n            rc = cli.main([\"flow\", \"run\", str(path), \"--minutes\", \"0\"])\n        return rc, err.getvalue()\n\n    def test_a_refused_profile_is_a_message_not_a_traceback(self):\n        \"\"\"Two commit steps: the validator refuses it (the T2 run).\"\"\"\n        bad = {\"name\": \"x\", \"list\": {\"item\": r\"(@e\\d+) link\"},\n               \"steps\": [{\"do\": \"click\", \"match\": r\"(@e\\d+) a\",\n                          \"commit\": True, \"proves\": \"a\"},\n                         {\"do\": \"click\", \"match\": r\"(@e\\d+) b\",\n                          \"commit\": True, \"proves\": \"b\"}]}\n        rc, err = self._run_cli(json.dumps(bad))\n        self.assertEqual(rc, 1)\n        self.assertIn(\"error:\", err)\n        self.assertIn(\"more than one\", err)\n        self.assertNotIn(\"Traceback\", err)\n\n    def test_an_unreadable_profile_is_a_message_not_a_traceback(self):\n        rc, err = self._run_cli(\"{ not json\")\n        self.assertEqual(rc, 1)\n        self.assertIn(\"cannot be read\", err)\n        self.assertIn(\"flow validate\", err)\n\n\nif __name__ == \"__main__\":\n    unittest.main(verbosity=2)\n");
